INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8431, '在战歌峡谷中与银翼哨兵的这场战斗至关重要。联盟打着保护一片本不属于他们的森林的幌子，企图夺走部落最大的一处木材来源。$B$B别让他们的图谋得逞，$N！带着你为部落建功的凭证回来见我！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The battle in Warsong Gulch against the Silverwing Sentinels is of great importance. Under
