INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8443, '我们与联盟的冲突已升级为真正的战争。到这一步，双方都不再需要、也不再期待以虚假的借口开战了。$B$B阿拉希盆地的战斗，说白了就是一场资源之争。资源要么被联盟夺走用来对付我们，要么被我们夺来支撑战争。帮助污染者维持我们所需的资源供给，$N！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Our conflict with the Alliance has escalated to a true war. No longer are false pretenses 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8595, '我看得出，你不是普通的凡人，$n。你对抗上古之神的胜算虽然微乎其微，却比我们此刻要大。毕竟，他防着龙族登门，却没料到会遇上你这样的人。$b$b正如阿纳克洛斯与鹿盔在千年前以凡人与龙族的联手击败了其拉虫人，我们也来立下盟约。赢得青铜龙军团的信任，你便赢得我们的信任。到那时，我们才会把你塑造成真正的勇士。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I see that youre no ordinary mortal, $n. Your chances against the Old God, however infinit
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8608, '你回来了？有意思。如你所见，我仍在为安其拉之战募集物资。也就是说，我还得请你再出去一趟，替我收集一捆魔纹绷带。期待你归来，$C。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You returned? Interesting. As you can see I am still collecting for the AhnQiraj war effor
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8751, '我从未见过如此坚毅之人！青铜龙军团再赐你一道附魔——是时光守护者本人要求的！$B$B把你的印章戒指交给我，我好做相应的调整。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The T
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8756, '我从未见过如此坚毅之人！青铜龙军团再赐你一道附魔——是时光守护者本人要求的！$B$B把你的印章戒指交给我，我好做相应的调整。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The T
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8761, '我从未见过如此坚毅之人！青铜龙军团再赐你一道附魔——是时光守护者本人要求的！$B$B把你的印章戒指交给我，我好做相应的调整。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The T
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9142, '规矩你懂，小子。一枚英勇徽记换一份工匠的委任状。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You know the drill, kid. One valor token gets you a craftsmans writ.
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39980, '什么样扭曲的心智才会去袭击平民？这场冲突中已有无数无辜者丧命，但有些人却专门以伤害无力自保者为乐。不只是男人，还有女人和孩子。这样的暴行不能不予回应。我们必须出手阻止。找出过去一天内不义击杀数最多的玩家，终结他们的屠戮。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- What kind of deranged mind attacks civilians? Countless innocents have died in this confli
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39981, '大屠杀有什么荣耀可言？没有，那是疯狂，而我们有责任阻止它。要阻止联盟与部落之间的战争吞噬我们所有人，就必须除掉那些最热衷于此的人。找出过去一天内荣耀击杀数最多的玩家，终结他们的嗜血。唯有如此，才能有和平。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- What is honorable about mass slaughter? Nothing, it is madness, and we have a duty to prev
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40739, '那么，又来换一根巨型香蕉了，是吧？我懂：那味道实在太惊艳，我自己也吃不够！$B$B我只需要你带来三根熟透的特尔阿比姆香蕉和一份梦境之尘。材料一到，我就能再为你转化三根大香蕉。没错，就这么简单！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- So then, back for another Gargantuan Banana, are you? I know: The flavor is so spectacular
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40740, '我改良了转化工艺，甚至扩建了实验室！一次造出多根巨型香蕉如今完全可能。当然，我需要的还是启动流程所需的材料。$B$B要造十五根巨型香蕉，我需要十五根熟透的特尔阿比姆香蕉，以及五份梦境之尘。若你想要一捆那种巨型香蕉，就把材料带来，我让你美梦成真！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I have refined my transmutation process and even expanded my lab! The ability to create mu
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41274, '你能感受到吗，$C？那弥漫在空气中的爱与倾慕的芬芳？那些热恋中的鸟儿彼此分享的喜悦与迷恋？见证爱在艾泽拉斯蔓延的奇迹，没有什么比这更让我心跳加速了！$B$B你的眼睛出卖了你的心，我读你就像读一本摊开的书。我能看出你渴望了解更多，甚至亲身去体验这份情感。爱有千般形态，并不总如人所想的那么分明。就连我这位爱的传令官，也常为我的箭所选中、蒙受爱的祝福之人感到意外！爱，真是个谜！$B$B不必再找别的证明——只看过去被我的箭射中过的那些人就够了。给我带来一份他们那份独特的爱与倾慕的信物，把这些纪念品带到任意主城交还给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Can you feel it, $C? The sweet fragrance of love and admiration that permeates the air? Th
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41275, '$N！你有空吗？你的珠宝加工手艺出类拔萃——我门下少有弟子仅凭我的教导就能达到这样的水准。不用大师也看得出：你天生就该把这门手艺磨炼到极致。$B$B虽说你已远远超出我的期望，可惜我能教的也仅止于此了。但这并不意味着你旅程的终点。还有比我更能胜任的导师，其中一位正是我的好友。也许你已与他相识——他有些多疑、爱抱怨，但只要稍加帮助，他就会倾囊相授。$B$B若你想专精此道、成为珠宝加工大师，就去秘法区找塔瓦斯德·基瑟尔吧。他的指点将为你在这行铺就前路。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N! Do you have a moment? Your skills in jewelcrafting are exceptional, rarely any of my p
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41276, '$N，再次见到你真是太好了。我注意到了——你自然也注意到了——你在这门手艺上的进步堪称飞跃！说真的，我已许久没见过如此天赋异禀的双手。可惜这也意味着我的教导到此为止了。不过你求知的热切显而易见；好在我还能最后帮你一次。$B$B若你想在珠宝加工上更进一步，就去卡加斯找我的好友加卡尔。险恶的荒芜之地不是我这种尸体该待的地方，但像他那样结实的巨魔，再恶劣的环境也应付得来。去找他的路上务必小心，愿你一路平安。$B$B<古尔迈尔短促而诚挚地鞠了一躬。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N, what a splendid sight to have you here with me once more. I have noticed - and you sur
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41277, '$N！你有空吗？你的珠宝加工手艺出类拔萃——我门下少有弟子仅凭我的教导就能达到这样的水准。不用大师也看得出：你天生就该把这门手艺磨炼到极致。$B$B虽说你已远远超出我的期望，可惜我能教的也仅止于此了。但别灰心——我自己的师父瑟格伦，或许能在我不及之处助你一臂之力。$B$B若你想专精此道、成为宝石切割大师——那门操控宝石以增益自身本领的技艺——就去找瑟格伦。他属于一个比我们现今任何文明都更古老的团体，却选择了隐士的生活，独居于荒芜之地的荒野。去古城科尔桑的废墟附近寻他。他不与任何人交谈，但若你把这块水晶拿给他看，我向你保证——他会听你说明来意。路上务必小心，去那片荒凉之地的旅途十分凶险！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N! Do you have a moment? Your skills in jewelcrafting are exceptional, rarely any of my p
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41278, '$N，再次见到你真是太好了。我注意到了——你自然也注意到了——你在这门手艺上的进步堪称飞跃！说真的，我已许久没见过如此天赋异禀的双手。可惜这也意味着我的教导到此为止了。不过你求知的热切显而易见；好在我还能最后帮你一次。$B$B若你想在宝石学上更进一步，有个人或许能助你达成志向——一个神秘莫测的人。他比我所知的一切都更古老，属于一个曾掌控艾泽拉斯矿物知识的古老团体。因此他极重隐私，也就是说，他多半不会与你交谈。来，带上这块水晶。它是我曾在他门下受教的凭证，也能让他知道你可以信任。路上务必小心，愿你一路平安。$B$B<古尔迈尔短促而诚挚地鞠了一躬。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N, what a splendid sight to have you here with me once more. I have noticed - and you sur
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41279, '<你猜想，那该算是这位土灵脸上的笑容。从巨人身上取下的粗糙宝石，在他宽大的手掌里显得很小。他只点了点头，便示意你再次跪下。$B$B当他的手掌再度按上你时，眼前的景象清晰了许多，尽管这过程仍令你吃力。三颗宝石浮现在你内心的视野中。幸好你认得它们：一颗烬石、一颗星红宝石、一颗黄水晶。接着，你看到这三颗宝石被切磨成一种你从未见过的刻面。你凝神细看，把那些动作一一记下。这份智慧已深植你心。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <You assume what you are seeing is a smile on the Earthens face. The rough gemstone from t
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41280, '<视野恢复时，瑟格伦正摆弄着双手之间的什么东西。凑近一看，他毫不费力地把一颗星红宝石切成了你方才见过的刻面。他把宝石放到桌上时，手中又可见另一颗宝石——一颗黄水晶。他重复了同样的过程——接着又用烬石做了一遍。$B$B手艺人用生硬的目光指指你，指指他的作品，然后摊开空着的手掌。你琢磨片刻，终于明白他的意思：他要你把刚学会的三种切割各做五遍。$B$B应该不太难，对吧？>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <Regaining your vision, Thegren is tinkering with something between his hands. Upon closer
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41281, '<不必他示意，你便跪下，接受新师父教诲的下一幕幻象。$B$B洁白的厅堂、无尽的瀑布，一股暖意充满你的脑海。在遥远的西方，卡利姆多大陆上，凄凉之地的山峦深处，正是这幻象的源头。曾是圣地的玛拉顿洞窟中，藏着你下一个目标：又一个巨人，这一回是纯净大理石之躯。你需要取回他石身上的一块石板。$B$B你重新站起，向瑟格伦点头，他只是以拳捶胸，便又埋头于自己的工作。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <Without having to gesture anything, you kneel down to receive the next vision of your new
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41282, '<瑟格伦面前的桌上摆着三样东西：你从波尔加斯特身上取下的命脉宝石、兰斯利德的大理石纹石肤，以及一块似乎不受岁月侵蚀的精致布料。你仔细端详了许久，转向瑟格伦——他只是面无表情地看着你，不过他那张石雕般的脸本来也看不出什么。$B$B看来这是你最后的考验。用你学到的宝石切割本领，把这颗灼热的石头切磨成完美的形状。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <On the table before Thegren are three things layed out. The Lifeblood Gem you took from B
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41283, '好吧，听我说，我就跟你实话实说。我教你那些秘传工艺，绝不是因为我乐善好施。我向你保证，绝对不是。相反，你要帮我……补充库存，作为交换，你会得到关于我金饰加工的一小份真传。行不行？就这么定了。$B$B请尽快把下面这些东西给我带来，我可不是那种愿意久等的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Alright, listen, let me be honest with you. I will not teach you my secret crafting techni
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41284, '信不信由你，住在山底下并不代表你的库里就有源源不断的宝石。而且要是有些子虚乌有的谣言让你没法在这儿做正当生意，那更是雪上加霜。要是我还在诺莫瑞根，这些事都会容易得多，相信我。可话说回来，宝石是珠宝加工的命根子——没有宝石，就没有珠宝，没有买卖，没有钱，付不起房租。你懂的。眼下我急需讨房东欢心，所以需要不少那种闪闪发亮的小宝贝来弥补损失。$B$B我们想到一块去了吧？当然。把下面这些宝石给我带够，我会分你点小东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Believe it or not, but living under a mountain does not guarantee you a steady flow of gem
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41285, '不管别人跟你说了我什么——全是谎话！我百分之百、从来没有给任何人做过什么受诅咒的东西。我对手艺有操守，也立过誓！别问我跟谁立的誓。绝对保密。而且绝对、绝对不心虚。$B$B话说回来，似乎某个倒霉冒险者的厄运现在落到我头上了，又一次往我名声上泼脏水。有个大胆的法师找上门来，要一条能增强法术的项链，好去北方那座新近重新发现的吉尔尼斯城探险。我当然照办，给他做了一条——反正房租到期了。可他在那鬼地方的探险，结局嘛……对他算不上好。糟糕的是，他那帮冒险者同伴现在把他的死算在我头上，在铁炉堡到处说我在项链上附了邪咒！$B$B$N，我要你亲自闯一趟吉尔尼斯城，把那条项链给我带回来！我最不愿看到的，就是有人拿它当假证据来对付我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Whatever youve been told about me - its all lies! I one hundred percent NEVER made any sor
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41286, '到此为止了，好心的旅人。我能教的，你在别处也差不多都能学到。不过，若你求知的渴望不肯就此打住，那我就告诉你我这些巧妙本事的来处。$B$B按理说这话我不该说，但你帮了我的大忙，我不能让你空手而去。向西去，在凄凉之地那片险恶的平原上，你会找到我自己的师父，他离群索居。虽说他喜欢清静，但我知道他不介意有人作伴。若他一开始不搭理你，别泄气——对于那些想求知识的人，他最看重的正是执着！$B$B去找一座俯瞰大海的高塔，那是我最后一次见到他的地方。既然话都说到这儿了，你最好快点走，免得我房东以为我在搞黑市买卖！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- This is it, good traveler. There isnt much more I could teach that you couldnt learn elsew
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41287, '老实跟你说，在这荒野里，我们的物资并不充裕，没法正经教你。我可不像奥格瑞玛那些矮个子绿皮朋友那样资源无限。不过，这难不倒我们。幸运的是，这片土地自然资源丰富，你可以把它们变成上课要用的材料。$B$B就当是一次测验，看看你到底有多少本事。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I will be honest with you, out here in the wilderness, our supplies are not as plentiful a
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41288, '你自然知道，宝石、贵重石料与矿物是珠宝加工的根本。没有它们，做出时髦的饰品固然还是可能的——但说实话，那还有什么意义？依我之见，一颗精致的宝石，甚至一颗华丽雕琢的宝石，才是赋予首饰目的与意义的关键。$B$B给我带来足够多的艾泽拉斯宝石，我们好一起分析它们的特性。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Like youll surely know, gems, valuable stones and minerals are essential to jewelcrafting.
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41289, '我族在金银加工与镶嵌点缀方面有着悠久的历史，无论是可拆卸的还是永久的。我固然会与你分享古老的赞达拉金饰加工传统，但把眼界扩展到其他知识来源同样重要。$B$B我要你去钻研的，是人类制作仪饰章的做法。向北去，离我们那些被遗忘者盟友的领地不远处，你会找到吉尔尼斯这个国家。据说它是旧时代的遗存，如今刚刚向那些勇于挑战其凶险之人敞开。在它那山脊般的高塔之上，便是吉尔尼斯城——据旅行的冒险者说，那是个商业、贸易与庆典之地。$B$B你会在那里找到一份适合我们分析的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- My people have an extensive history about goldsmithing and bedazzlements, be it removable 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41290, '好心的旅人，谢谢你让我能重拾这门许久无法施展的手艺。我曾立誓要继续磨炼技艺，可这些年为部落效力，让我再也无法顾及这个誓约。不过，若像你这样的冒险者再多来几位，或许我终究还能做到。$B$B为了答谢你及时的帮助，让我好好报答你——告诉你我是在哪里练就金饰加工本领的。向西去，在凄凉之地那片险恶的平原上，你会找到我自己的师父，他离群索居。虽说他喜欢清静，但我知道他不介意有人作伴。若他一开始不搭理你，别泄气——对于那些想求知识的人，他最看重的正是执着！$B$B去找一座俯瞰大海的高塔，那是我最后一次见到他的地方。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Good traveler, thank you for letting me practice this craft I had long been unable to. I h
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41291, '这么说，你非要学这门金饰加工的手艺不可？我通常亲自挑选弟子，可是……既然我从前的一名学生推荐了你，甚至让你一路探寻到此，我实在无法拒绝你的请求。我们本可以立刻开始，只是眼下有一桩小小的麻烦。我在海滩上收集被浪冲上岸的矿物时，不幸弄丢了我珍爱的珠宝匠工具包。一头海巨人惊到了我，我只得弃包而逃，此后一直没能找到安全的时机取回。我的战斗岁月早已过去，所以若你想学我的手艺，就得替我把工具包取回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- So you are adamant to learn the art of Goldsmithing? Usually I pick my pupils, yet… If one
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41292, '你可以称我为巧匠，年轻人。数千年前伟大的埃瑟瑞拉斯城陷落时，我舍弃了从前的名字。此后我游荡在卡利姆多的荒野间，把智慧传授给凡人族裔中我认为值得受教的人。派你来的那位朋友——尽管听来难以置信，他正是我教过的弟子之一。看来他对这门手艺的热爱并未随时间消退，这倒令人欣慰。$B$B你想学习那些流传数百年、在种族、文明与世代之间传递的金饰加工技法？那就向我证明你的本事。让我看看，你能把大地的血之声听得多清楚。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You may address me as The Artificer, young one. I abandoned my previous name when the grea
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41293, '你是说，他教了你一些本事。那么请放心，他掌握的知识大多是我传给他的。他或许是个熟练的珠宝匠，但这门手艺中更隐秘的诀窍并不在他那里。若想潜入一门技艺的深处，就必须对它的表层有透彻的理解。$B$B这正是我要你做的：把你对金饰加工的基础知识展示给我看，我才知道该从何处教你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- So he taught you some of his skills, you say. Well, rest assured, most of the knowledge he
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41294, '真正的匠人会把生命的方方面面融入作品：生、死、天与地、在我们世界中起作用的各种元素。你或许已经知道，艾泽拉斯的宝石蕴含着潜藏的魔力与元素属性，落到对的人——或错的人——手里都会极为强大。$B$B向我证明，你能在制作首饰时恰当地驾驭艾泽拉斯宝石中的能量。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- A true artisan encompasses all aspects of life into his work. Life, death. Heaven and eart
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41295, '过去几百年里我有过许多弟子，说实话早记不清有多少了。但其中有一位，永远鲜活地留在我的记忆与心里。那是个年轻的精灵，肤色白皙，我此前从未见过那样的。她对金饰加工的好奇与热切无与伦比——那正是我在她少年心性中所欣赏的特质。$B$B她毫无偏见地对待这门手艺，把它视作心灵与灵魂的表达。当她完成最后一件作品——一柄品质非凡的法杖——冒险之风便把她卷走了，从我身边带走。我曾盼望她终有一日回来，哪怕只是来看看，可惜重逢终究没有发生。$B$B她的存在——以及她的不在——在我身上留下了印记。因此我要求每一位后来的弟子都具备她对手艺那份澄明的眼光。向我证明，你能追随她的榜样。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Ive had multiple pupils in the past centuries, and frankly Ive lost count on how many ther
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41296, '我的人民已经分裂。逃离故土以来，为了寻求安宁与栖身之地，我们历经磨难。避难所的同胞们仍然坚韧，紧抓着希望不放，但那些失落者就不是如此了。疯狂已深深攫住他们的心智，根须早已无从切除。他们徒劳地想要回到德拉诺那片地狱般的故土，于是收集德莱尼水晶——那种来自那里的强效宝石——却不知道自己根本无法正确使用它们。可事情当初并非如此。$B$B他们之中曾有一位强大的裂隙行者，名叫库米沙，他与荒芜庇护所那些发狂的德莱尼人分道扬镳。如今他游荡在南方那片险恶的平原上，追寻神话与传说。我要的正是他关于我们神圣水晶的学识——若你能说服他加入我们，请务必一试。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- My people have been divided. Weve endured much on the escape from our home, in search of s
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41297, '我把那些失落者抛在了身后。他们的首领已成了淌着口水的蠢货，对着神圣的德莱尼水晶垂涎三尺，忘了自己真正的潜能。桑夫·克拉也不例外，希望毒害了他和他追随者的心，让他们看不见自己正困在一个贪婪的世界里。你也是。否则，你站到我「收藏家库米沙」面前，还能是为了什么？不就是为了从我这里夺走你想要的东西？但我了解你和你的同类——而正是你的贪婪，会推动我的野心。$B$B这些被诅咒的土地上游荡着失去心智的德莱尼人，他们使用裂隙穿行的魔法，却没有驾驭它的本事。在无止境地搜寻德莱尼水晶的过程中，他们失了神智，像虫豸一样翻刨沙土。全都是疯狗！他们袭击了我的营地，偷走了一批珍贵的宝石。把他们杀光，取回我的东西，我或许会赏你几分用处。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I left the lost ones behind, their leaders have become bumbling fools drooling over the sa
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41298, '<库米沙研读着那卷外族卷轴，他那不断变幻的身形忽隐忽现。读完之后，他愤怒地把羊皮纸撕成碎片。>$B$B卡拉托卡尔！他们在想什么？这是对所有德莱尼的亵渎，亵渎！他们像工蜂一样在这片死亡之地上游荡，令人担忧，倒还不算危险。可他们的目的，就危险得多了。据这份经文所述，你遇到的那些追寻者正在为一个卑劣的生物收集德莱尼水晶——一个名叫马托加的裂隙行者。单是这一点就已冒犯了我的志向，而他的真正目的更是令人作呕，必须阻止。若他能把水晶带回德拉诺，我们唯一归乡的途径就会断绝——我们将被判在腐烂与衰败中了此一生，永远被囚禁，再也见不到家园。$B$B你不会让这种事发生的，因为库米沙会赐予你所求之物；代价是他的首级。他在我营地西北方等候他的追寻者们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <Kumisha is studying the foreign scroll, his shifting body fading in and out of view. Afte
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41299, '拿去，把这卷卷轴带上。你，还有那个天真的桑夫·克拉，都能从上面找到我关于德莱尼水晶及其用途的学识。他尽可以照自己的打算去做，只要不妨碍我的计划。听从我的警告对他最有利，否则他会落得和马托加一样的下场。$B$B至于你，我只有一句话：除非你愿意继续为我效力，否则我不想再看到你。若是不愿，就滚吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Here, take this scroll. On it you and the naive Sanv Kla will find my knowledge of Draenet
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41300, '哦，糟了！一个侏儒能倒霉到什么地步？我犯了个可怕的错误，现在代价是我的脑袋，或者更糟——我的家！$B$B简单说，我的钱袋干得见底了，见底得厉害！我当时走投无路，就接受了一个来路可疑的商人的提议，他许诺给我成堆的黄金。可等他第二次上门，身边却带着两个吓人的打手，还向我索要远超约定的货物！我苦苦解释我的库存根本不够他要的，可他们充耳不闻——现在他们还在威胁我。威胁我！慷慨无双、无人能及的塔瓦斯德·基瑟尔！$B$B求你帮我解这个困局！我保证，你会得到应有的回报。那些恶棍往贸易区去了，我敢肯定这帮贼就藏在外环那一排排房子里！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Oh, this is bad! Just how unfortunate can one single gnome be? I made a horrible mistake a
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41301, '那么，你来做什么？来好言好语求我别再纠缠你那位不肯履约的朋友？还是打算用更……直接的办法解决问题？不管哪种，我都遗憾地告诉你，都行不通。期限是我们这行最看重的东西，而那些没能按期交付的人……$B$B<他朝站在你身后的两名凶悍护卫比了个手势。>$B$B不过，我是个待客殷勤的商人，不会因为对令人失望的交易对象心存恶感就放过机会。所以我给你个提议：把塔瓦斯德还欠我们的货物交付双倍，我和我的同伴们可以考虑放过他。这提议很合理吧？我要是你，就会尽力答应下来……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- So what are you here for? To ask me nicely to stop harassing your friend who doesnt want t
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41302, '<莫索格用放大镜仔细检视着货物。他查验的时候，你能感觉到那两名保镖就贴在你身后喘气。这位来路不正的商人查验完毕，把首饰收进箱子，扔给你一袋钱。>$B$B和你做生意很愉快。我建议你现在就回你朋友那儿去，你们俩以后都别再在这儿露脸。滚吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <Motsog inspects the wares meticulously with a lens. While he does so, you can feel the bo
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41303, '灾难，这简直是场灾难！一场金钱上的末日降临到我头上；我的名声被毁了，我的声望也荡然无存。我那些值钱的首饰正运往藏宝海湾拍卖，其中有一枚格外贵重的大戒指。我以为它们已经平安抵达那座港口城市，就没多想继续干活——却不知道它们压根儿没离开过棘齿城！如今我成了那些体面商人和拍卖师的笑柄，他们正乐呵呵地嘲笑着我的无能。$B$B伙计，你能帮我收拾这个烂摊子吗？我信得过的承运人格里兹比踪影全无，而我丢不起那些无价的杰作。既然没有线索，不如先在棘齿城里四处打听打听。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- A disaster, thats what it is! A monetary apocalypse is upon me; my name sullied and my fam
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41304, '我认识格里兹比很久了，那家伙很爱交际，你知道的，朋友一大堆。干这行自然如此。他来到码头时我正在忙物流的事，因为下一班船还早得很，我们就聊了几句。$B$B我们正闲聊打发时间，另一个地精凑了上来，那样子活像见到了失散多年的亲兄弟。他俩关系一定很近，因为格里兹比看上去也跟他很熟。他们聊什么我没听清，但隐约听到他们说要往南去，不知为了什么。$B$B已经过去好些时候了，我担心格里兹比凶多吉少，请你务必确认他是否平安。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Ive known Grizzby for a long time, a sociable bloke, yknow, lots of friends. Comes with th
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41305, '这份契约我要亲自带给纳特，他该知道我们以前的雇主在科赞有什么图谋。要是做得到，我真想大摇大摆闯进安德麦，把他们的贸易亲王扔进最深的贫民窟里去。可我做不到，所以只能把手头能做的做到最好。$B$B首饰被偷，物资又将耗尽，下一次拍卖我几乎拿不出任何东西——而我在那场拍卖上必须拿出一件响当当的物件，否则我的名声就彻底完了。我看得出你手巧又有天赋，愿意再帮我一次吗？$B$B我要的是一颗大得夸张的宝石。来斯帕克沃特的旅人们传说，血色十字军手里有一颗拳头大的红宝石，我想他们的首领就随身带着。另外，还要一条素净的金项链，好让我把红宝石镶上去；这点活你自己就能敲打出来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I will bring this contract personally to Nert, he should know what our former employers ar
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41306, '我跟你讲，我这人就是命里带霉。你看，如今贸易航线上四处都是海盗，用船运货就跟把货仔仔细细系上蝴蝶结、亲手递给那些亡命徒没什么两样。所以显然不行。另一个办法是走陆路，风险一样大，你肯定明白我在说什么。$B$B不管怎样，我选了后一条路。因为我真的、真的必须把这批货送到，我就在棘齿城找了个最吓人的食人魔，付钱让他一路护送我去热砂港。可惜我们遭到亡灵野猪人的伏击，食人魔和我那批宝贝货全被他们掳走了。$B$B我快绝望了。你能去剃刀高地帮我把货取回来吗？我不觉得货还在那个食人魔护卫身上，但要是他还活着，他会知道货在哪儿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I am cursed with bad luck, Im telling you. You see, with all the pirates roaming around th
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41307, '萨赫希很抱歉，没能办到。萨赫希不够强壮，保护不了绿色的朋友，可恶的野猪人把萨赫希带到了这里。他们想吃掉萨赫希，可是妈妈说萨赫希太胖了，也许不太好吃。$B$B你要是来找特拉西斯的箱子，它就在这儿，可是他们打可怜的萨赫希、逼他快走时，石头全掉出来了。现在那些亮闪闪的宝石都在可怕的僵尸和鬼魂手里！萨赫希想回家，你能帮萨赫希把特拉西斯的宝石收起来、送到塔纳利斯那个小侏儒那里吗？特拉西斯说她在海边的小镇等着这个箱子！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Sahrhee is so sorry he failed. Sahrhee was not strong enough to protect little green frien
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41308, '好吧，当我刚才什么都没说。我绝对不会再从他那儿订货了。这些宝石的表面全是脆的！怎么会这样？他对它们做了什么？$B$B<你把宝石如何落进几具亡灵肚子里、又如何被它们的体液侵蚀的经过讲给凡兹听。>$B$B呃，你不用讲得那么细。真恶心。好吧，真是妙极了。现在我手上又多了一堆活，而这是我眼下最经不起的。所幸你在这儿能搭把手。哦，别摆那副表情，我付你钱，不找特拉西斯要——他最好别在近期带着那张脏脸出现在这儿。$B$B要修好这些宝石，得用点更有劲的东西，普通的宝石油在这儿不顶用。往南不远处的海边有个小湾，你在那儿能找到一个……就说是我的一个生意伙伴吧。把海岸边钢颚钳嘴龟身上的油腺、一份强效秘法精华和一个水晶瓶带给他。就说是我让你去的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Okay, scrap what I just said. I will definitely not order from him again. All these gemsto
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41309, '<扎拉什吉把油腺挤进水晶瓶里。他沙哑地低吟着含混不清的词语，施出一道陌生的法术，瓶中的液体泛起鲜亮的光芒。>$B$B拿去吧，外乡人。这油能封住宝石表面的裂纹，同时又不妨碍精细的切割。现在走吧——我允许她常来同我往来，可对你，我就不能这么说了。我或许比我那些同胞更好客，但这不代表我的耐心没有尽头。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <Zalashji squeezes the oily glands into the vial. Muttering unintelligible words under his
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41310, '<你找到的这本书不像周围其他典籍那样古老。书上装饰着肯瑞托的印记，你猜想它必定属于某位强大的法师。$B$B翻过书页，你判断这是一位名叫卡德加的法师的日志——你从前听说过他。他曾是守护者麦迪文的学徒，也是洛萨之子的一员，那支队伍在二战期间率领联盟远征德拉诺。$B$B你期待又揭开一个谜团，于是更专心地研读起其中的内容。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <The book youve found looks not as old as the rest of the tomes lying around. Embellished 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41311, '阿尔萨斯奉他那群恶魔主子的命令围攻达拉然时，我就在场。米奈希尔为盗取麦迪文之书犯下滔天罪行，他的军队同时洗劫了城市，抢走了我们存放在宝库中的其他危险遗物。为保卫这座魔法之城，我们拼死抵抗，我曾直面一头寻求毁灭与混乱的强大末日守卫。$B$B你要找的若是坦拉尔之握，那就必须找到那头末日守卫。达拉然陷落后，我疗养期间，其他幸存的法师讨论过阿克蒙德和他军队的下一个目标——结果他们向西而来，正是这片土地，为的是追逐世界之树诺达希尔。若那头末日守卫仍在艾泽拉斯，我猜他正在某个恶魔横行的深渊里谋划复仇，就在海加尔山附近。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I was there when Arthas besieged Dalaran under the order of his demonic overlords. While M
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41312, '当年在达拉然由肯瑞托保管时，我曾仔细研究过那件握物的形制、功用与用途。麦迪文虽是个讳莫如深的人，但他的法器与饰物上都带着同一种魔法标记，哪怕不熟悉守护者的法师也能感觉得到。研究过程中我得出结论：那件握物是某个宏大之物的一部分，而那个宏大之物又是更伟大之物的一部分。从它的形制判断，其顶端本应嵌着一颗巨大的宝石。$B$B若你在那座闹鬼的高塔中遇见这样一颗宝石，我有信心把这件古物复原如初。不过要做到这一点，我需要一个强大的奥术聚焦物来引导我的能量。守护艾泽拉斯魔法的蓝龙军团掌管着这类物件，但只有他们中最强大的成员才会随身携带。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- When the clutch was in the Kirin Tors safekeeping in Dalaran, I studied its form, function
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41313, '这片土地魔力充盈。我到此研究有许多原因，其中之一便是贯穿大地的众多地脉。强大的奥术能量自它们流淌的脉络中涌出，吸引着此界与他界无数渴求法力的居民。我想更清楚地弄清，为何这片被遗忘、被诅咒的土地会成为这种现象的所在。你眼中露出好奇——你打算协助我的研究吗？$B$B塔中另有事务缠身，所以若你愿意出去为我收集一些材料，我会给你相应的报酬。我需要的是地脉能量的结晶构造。我的学生在此地以东和以南各找到一处。我猜当地的蓝色龙人和堕落的血精灵是我们最好的线索。就从那里查起吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- This land is rich in magic. Numerous reasons brought me here for my research, and the many
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41314, '这两块水晶的整体结构完全相同，只有那块朱红的不同——当我用一点自己的魔力与之共鸣时……$B$B<克希雷姆把极微量的一丝法力导入红色水晶，顿时迸出猛烈的电火花与闪电。>$B$B听着，我们现在掌握的事实是：蓝龙军团不知出于何种我们尚未查明的原因，从门纳尔湖收集生长被某种手段人为加速过的地脉水晶。当地的血精灵也持有这类水晶，只是形态不同、更不稳定。这两件事是否相关，正需要我们去查清。$B$B我会继续测定这些水晶的稳定性，你则去替我取回一件珍贵的遗物——完成研究需要它。我从前的一名学生愚蠢地以为，把它带出我的塔不会有人察觉。萨纳斯告诉我，她匆匆往东去了木喉要塞附近，无疑是仗着与他们的交情藏身其中。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Both of these crystals have the identical integral structure, except the vermillion one - 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41315, '聚焦宝珠既已取回，就只剩下最后一件事需要确认了。来，带上这些水晶和宝珠，把它们放到我塔前的基座上。我在宝珠上施的法术会与地脉水晶产生反应——但愿如此——从而证实我对它们本质的推论。$B$B别害怕，我会在塔中注视着你，必要时出手相助。以你的本事，我们不必太过担心，但别忘了：谨慎是智者的命脉。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- With the focus orb returned, there is but one last thing we must assure ourselves of. Here
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41317, '我大半辈子都在研究这套传说中的珠宝加工百科。据传它们出自一个古老社会之手——我们如今所知的人类种族的先祖。考古学家正发现越来越多他们的废墟，人们称他们为阿佐萨。至今只找到五部他们的典籍，据说共有十一部。我的一位同样古老的熟人真的打开过一部——他把里面的情形告诉了我。他说那些书是用元素符文封缄的，那是艾泽拉斯元素生物口中念出的远古词语。此后我便一直在钻研它们，而这道锁上的火焰符文，看来正是布拉兹符文。$B$B我们需要一块与那道符文同调的元素生物的碎片。听说黑石山最深的洞窟——熔火之心里满是烈焰元素。我相信在那里最有可能找到我们要的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Ive been researching this legendary encyclopedia of jewelcrafting most of my life. It is r
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41318, '好吧，兵来将挡。先看这一页，看看上面写了什么……「欲明此经文，须献土与火之心于我。取出之热，将揭示你所求之知。」这些阿佐萨可真爱打哑谜。我只能猜，但我相信这情形和之前差不多：只有备齐相应的材料，才能解开这本魔典的秘密。$B$B土与火之心……这必定是指强大元素生物的烈焰之核与熔岩之核。取出之热……或许就是火焰精华？对，一定是这样！$B$B$N，你知道该做什么。我在这儿等你把材料带来，同时我也会尽力琢磨这本“非凡之书”。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Okay, we got to roll with the punches. Lets work with this page first and see whats writte
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41319, '我越读——不如说越是读不出——就越觉得这些典籍的种种玄机，不过是某个鼻涕虫地精想快点捞钱的把戏。两页可怜巴巴的纸上写着东西，而这一页上甚至只有一句话！「以结晶之血导引日光。」这到底是想说……等等！我灵光一闪！$B$B<凡兹翻找着自己的行李，抽出一张图纸。>$B$B这是一件我始终没做成的珠宝透镜的设计图。它能把光线聚成一道极具威力的射线，用来在金属上雕刻。它需要非常特定的材料——这就轮到你出场了。「结晶之血」一定是指极难得的山中之血，产自黑石山深处。我还需要透镜的框架，黑石深渊的菲诺斯·暗脉据说拥有一块连山中最炽热的高温都损不坏的透镜。把这两样带来，我就能鼓捣出一件工具来破解这一页！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The more I read - or rather DONT read - the more I believe all the mystery about these tom
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41320, '我经历了一段险恶的旅程，陌生人。一段跨越世界的旅程——是的，世界。裂隙行者拥有古老的魔法，那是艾泽拉斯从未有过的巫术。施展此术需要大量能量，而经验不足的裂隙行者常借助德莱尼水晶——我们故土生命之血的具象——来完成。桑夫·克拉让你来找我，是明智之举，因为我从回乡之旅、回到德拉诺的旅途中归来，至今仍惊魂未定、筋疲力尽。$B$B坐下，听我说。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I have a perilous journey behind me, stranger. One that transcends worlds; yes, worlds. Ri
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41321, '在着手拯救我的部族之前，我们自己和我随身的物件都需要准备。裂隙行走对施术者的心智消耗极大，被打断的裂隙行走更是如此。若我的心智之力不能恢复，救援便无从谈起。$B$B我的人民发现，吞食生物的脑髓能极大加速心智的恢复。这野兽越聪明，你恢复得越快。我在岸边见过蛇人游走，其中一些还能自行施法。给我带几颗这些施法者完好的脑髓来。$B$B但愿你们世界的物种真有我想象的那么聪明。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Before we can tackle the saving of my tribe, we need to prepare, both myself and my belong
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41322, '暴露在扭曲虚空的洪流中是件危险的事，它的余波至今仍折磨着我的身体。德莱尼人有自古流传的方剂，用来对抗长期裂隙行走的后遗症。虽然我弄不到那些传统材料，但我相信此地的本土生物足以配制出替代的药剂。$B$B我向东勘察时，遇到了一些吓人的生物，长着粗壮多肉的大钳——它们的肉应该能提供足够的养分。往西，其实不远，有些毛茸茸的家伙在采摘气味浓烈的草药。从那股气味判断，我确信它们有药用价值。两样都给我带够，我就能为疲惫的身体熬一副药。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Being exposed to the currents of the Twisting Nether is a dangerous act, its ramifications
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41323, '如今我已恢复元气，下一步便是取回我最珍视的物件：我的裂隙行者法杖。当初我被困在这些崖上的赤褐草地间，四周尽是狂躁的生物。其中一些头生尖角的恶物身负阴邪的妖术与诅咒，长相让我想起燃烧军团的恐怖。我无力地躺在地上，它们像掠食者扑向受伤的野兽那样逼近我。我勉强逃脱，却把裂隙行者法杖落在了那里——这一失误令我痛心不已。$B$B不过，即便把法杖取回，我那次失败的裂隙行走也已让它耗尽力量、毫无用处。我需要为它注入一缕力量的余韵——取自一位禁忌技艺的大师。在悲伤沼泽那头，一座沉没的神庙高踞树冠之上，里面有位精于巫术的强者，统御着死去的巨魔与巨龙。终结他对神庙与沼泽的掌控，并把他的力量具现带一份给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Now that I feel rejuvenated, our next step is retrieving my most prized possession: my rif
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41324, '眼下你在这里能做的也只有这些了。让我的裂隙行者法杖与新力量同调所需的时间比我们来得及的更久，所以我需要你继续前行。我留在法杖上倾注力量时，你前往诅咒之地——悲伤沼泽以南那片荒芜的废土。俯瞰红色沙漠的山丘顶上，我的学徒卡斯塔尔在等候。在这一切发生之前，我命他去勘察黑暗之门附近可疑的能量波动。他一定在为我担忧不安，去告诉他，不必再为我的安危担心。$B$B找到他之后，告诉他我会在避难所与他和你会合，好为那些但愿不会到来的变故做准备。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- For now, this is all you can do here. Attuning my riftwalker staff to this new power will 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41325, '师父派你来真是太好了。我们真该感谢他的先见之明，因为我方才目睹了极可怕的东西。你右侧那座可憎的黑暗之门，正是兽人入侵你们世界的遗祸——看见了吗？师父对传送门能量的怀疑是对的。就在你到来之前，一股巨大的能量涌动和一阵骇人的压迫之力席卷了这片沙漠的红沙。$B$B我的直觉告诉我，徘徊在它面前的那个东西强大得可怕。$N，请千万不要独自面对它。虽说师父信任你，但我们眼下的对手，恐怕不是你一人能应付的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Master did great by sending you to me. I am sure we can thank his clairvoyance for that, a
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41326, '快，赶去避难所，向桑夫·克拉示警！若我们不能及时撤离所有人，谁知道会有怎样惨烈的灾祸降临！我会在此期间尝试联络阿克扎多尔大人，但愿他能比预料中更早赶来相助。$R，我把全部希望都寄托在你身上了。也许还来得及。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Quickly, rush to the Harborage and warn Sanv Kla! If we do not evacuate all in time, who k
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41327, '要做的事还有很多，避难所里一片混乱，许多人受了伤。请见谅，我得去照料同胞。虽说任何帮助都值得感谢，但我必须坚持这事暂时交给我们自己。你已经做得够多了，再开口要你帮忙就太失礼了。$B$B不过在你离开之前，阿克扎多尔想再和你谈一件要紧的事。他在外面等你。恩基尔·托拉尔，朋友，愿你诸事顺遂。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Much needs to be done, the Harborage is in disarray and many have been injured. You have t
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41328, '$N！再次见到你真高兴。你近来可好？我们仍在重建之中，但多数人的士气依旧高昂。也有些人仍为我们可能面临的不确定未来而忧心。$B$B我一直在研究我给你的那颗纯净德莱尼宝石，我确信凭我从制作它时获得的知识，能够再造一颗。复制这个过程需要惊人的能量，但绝对值得你花这番功夫。若你还想要一颗，请把下面这些带来，我很乐意为你做。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N! A pleasure seeing you again. How have you been faring? We are still in the process of 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41336, '嗯，真奇怪。这一句……少了一个符文，没有它我就无法解读这段文字。看来我们卡住了。不过别以为我会就此放弃。少一个符文这种小事，吓不倒我。$B$B<巧匠从桌上取来一件小工具，看着像一根极细的杖，沿着书中字句缓缓移动。沉思片刻后，他再度面向你。>$B$B我知道该去哪里弄到那个失落的符文。这本魔典本身带有魔力，它的文字也是如此。我们要找的符文，可以用一个效果相近的替代品代替，而这样的东西能在通灵学院那些阴森的殿堂里找到。听说那是个骇人之地，但他们那些邪恶的研究正好能解我们的难题。从他们的亡灵法师导师那里取一枚这种形制的符文回来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Hm, how strange. This sentence here... It is missing a rune, and without it, I cannot deci
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41338, '$C，从神圣的海加尔山顶传来了消息。我们最大的恐惧——梦魇，已经扎根，并再度渗入我们的世界。许多勇敢的灵魂正前往那株巨大的世界之树，为同胞们平息梦魇影响的行动伸出援手。$B$B$N，我恳请你登上海加尔山，援助诺达纳尔的守护者们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $C, news spread from atop the sacred Mount Hyjal. Our greatest fear, the Nightmare, has ta
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41339, '$N，当我们的族人在清醒世界中奋战时，伊瑟拉与她的盟友——远古的荒野诸神——正竭尽全力、倾尽威能，抵挡着梦魇：那在翡翠梦境中扎根的不可名状之恶。$B$B多年前，第三次大战期间，山多·怒风与高阶女祭司语风曾在海加尔山低处的一座圣丘上与一位强大的存在会面。那里平日弥漫着那次会面残留的能量，可近来我们察觉到，不谐的波动正从那里向整座山扩散。鉴于眼下局势，我们最好尽快查明那背后藏着什么。$B$B$N，去南边暗谷隘口附近的那个地点查探，把你的发现带回来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N, while our kind fights in the waking world, Ysera and her allies, the Wild Gods of Old,
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41340, '艾泽拉斯的历史上，只有一位存在符合你所经历的描述——荒野之神玛洛恩，道途守望者。这世界尚且年轻时，他便已古老；在大分裂之前的岁月里，他是游荡于蛮荒原野的原始守护者之一。他庞大的力量与傲然的存在令敌人与同伴同样恐惧，而他那滋养自然的慈爱方式，又让他为后者所敬仰。$B$B你所经历的，太可怕了。一想到梦魇或许已经攫住了伟大的玛洛恩的哪怕一个碎片，就令人胆寒。我们必须立刻行动。$N，我向月光林地传讯的同时，需要你去收集二十块明亮的梦境碎片。它们对于让你免受梦魇侵袭至关重要。请为我们的目标出力，搜遍海加尔山的丘陵。无论你用什么办法弄到，都要快！$B$B凑齐之后，把它们带到月光林地交给守护者雷姆洛斯。他会给你进一步的指示。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- There is only one being in the history of Azeroth that fits the description of what you ex
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41341, '玛洛恩绝不能落入梦魇之手。对我们来说幸运的是，似乎只是他自身的一个碎片从翡翠梦境中的灵魂里分裂出来，而梦魇控制的正是这个碎片。可即便只是道途守望者的一个碎片，在这场本就对我们不利的战争中，也足以让敌人取得压倒性的优势。要洗去祖父身上的这份污秽，我们需要能让他想起亲族的遗物。$B$B塞纳留斯之枝是我父亲鹿角的一截。他在灰谷陨落后，我们先把他的遗体带到梣影，随后送回月光林地安葬。也许你能在那里的龙类中找到它。$B$B伊瑟拉是玛洛恩的挚友，也是我们父亲的养母。她青玉色皮肤上的一片鳞，必定对我们的目标大有帮助。她最钟爱的孩子们都持有一片。可惜它们中大多数——甚至可能全部——都居于翡翠梦境之中。$B$B最后一物，是伊露恩的纪念之物。她所选的守护者——枭兽——在冬泉谷保管着许多她的器物，去那里寻找吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Malorne cannot fall to the Nightmare. Luckily for us, it appears only a fragment of himsel
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41342, '来，年轻人，收下这支忆念权杖——它由你带来的遗物与梦境碎片所化。凭它，你将能抵御梦魇足够久，从它手中夺回玛洛恩的碎片。$B$B不过务必谨慎。梦魇不会这么轻易放走猎物。召集盟友与志同道合之人，救出我祖父的灵魂。$B$B速去，莫让他得以在我们这个世界显现。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Here, young one, take this Scepter of Remembrance, conjured from the relics and dream shar
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41343, '$R，来这里？求求你，别杀。别杀大胡须！大胡须是走错地方了。大胡须是被奇怪透亮的人类叫来的。大胡须只想走。可是大胡须走不了。不行。大胡须先要大大的蜡烛！$B$B大蜡烛对大胡须和朋友们很重要。对，对。大胡须给报酬，报酬，对！给大胡须带大蜡烛。好不好？$B$B去问看门人，看门人一定知道！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $R, here? Please, no kill. No kill Big Whiskers! Big Whiskers here by mistake. Big Whisker
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41344, '琢磨你的请求时，我拿不定主意，不知道是该发笑，还是该为你的神智担忧。你要这么大——我是说，这么巨大的——一根蜡烛，说明你打算在主人的藏书室里做某种实验。$B$B听你描述那根蜡烛得有多大才能办成你要办的事，再加上你那说不清道不明的进门手段，我承认自己很是矛盾。不过，我确实感到你身上透出一股不容忽视的力量，这让我相信你有本事在那些神秘厅堂里往来。$B$B话虽如此，我似乎记得，贵客大厅的尽头摆着一根相当大的蜡烛。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- As I ponder your request, Im left in uncertainty, not knowing whether to respond with laug
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41347, '我无聊到了极点。这永恒的炼狱虽不如你想象的那般痛苦，却乏味得令人难以忍受。我再也体味不到人间的欢愉，而我对手饰的热爱，也因再也无法佩戴而褪色。即便如此，我最珍爱的那件饰物也已不在我手中了。$B$B当年收到麦迪文的请柬时，我的行囊里带着成堆的珠宝与宝石。其中最为珍贵的，是一条价值无法估量的项链——纯净的艾泽拉斯钻石，缀在一条纤细的奥金链上。它的价值胜过这些闹鬼厅堂里任何客人一辈子的家当。唉，要是我死时还戴着它，我至今仍能欣赏它的美。可惜它早在你如今所处的年代之前许多年就被偷走了。我最后一次见到它，是在我离开暴风城宅邸之前。$B$B活人，帮我找回我的宝物，我会以麦迪文亲手赐予我的一件首饰作为报酬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I am bored beyond measure. This eternal purgatory I am chained to is not as painful as you
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41348, '你在找厄尔威克庄园？别逗我笑了。那鬼地方只剩个回忆，多年前就烧成了灰，我的梦想和希望也跟着一起烧了。你眼前看到的，就是厄尔威克这个姓氏剩下的一切——这么一堆可悲、一文不值的废物。$B$B<他打了一个粗哑的嗝，接着呕了出来，淌在他本就脏兮兮的衬衫上。>$B$B我们什么都没了，什么都没了！他们洗劫了我们的宝库，杀光了宅子里所有人。就连……就连我心爱的乔治娜……看着她躺在那里，毫无生气……我给她偷来的那条钻石项链还闪着光……那畜生，那个兽人，把它从她身上扯了下来——我虽然瞎了，可我看得见……在脑子里看得见！他还在笑，还在膜拜他的酋长，那个毁灭之锤！我永远忘不了那个怪物，永远！要是我在场，我会把他们全杀光，而不是关进收容所！$B$B不管你想从我这儿要什么，我都没有，别再问东问西！滚开，别烦我！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Yer looking for the Earlwake Estate? Dont make me laugh, that wretched place is nothing bu
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41349, '<幸运的是，你似乎挖到宝了。这本兽人日志的字里行间，记载着你正在寻找的那条项链的线索。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <Luckily, you appear to have struck gold. The pages of this orcs journal contain informati
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41350, '你端详这把剑，除了它明显的残破之外，并无异常。剑刃脆裂生锈，剑柄的皮革一碰就碎。意想不到的是，剑首竟完好无损，边缘刻着精细的花纹，上面写着：H. C.。此外，还能看到洛丹伦的徽记嵌在一弯新月之中。也许这就是剑主。若你运气够好，项链也在他那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Inspecting the sword, you see nothing out of the ordinary, besides its apparent dilapidate
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41351, '你带到我面前的这截断刃，属于洛丹伦最强的骑士之一——拉祖夫·伊瓦尔迪。洛丹伦被围的那命运之日，他一人一剑砍倒的兽人比其他任何士兵都多，皆是一击毙命。$B$B入侵者被击退后的那些天里，他被奉为英雄，因为正是他挡住了那个穷凶极恶的兽人女战士——她曾像切黄油一样切开我们的队伍。作为她殒命的战利品，他从她身上取下一条美丽的钻石项链，此后珍重地保存着，宣称那是他最大功绩的证明。$B$B他是个好人，也是我的朋友，但他对那挂坠及其意义的执念吞噬了他。我最后一次见他，是他跟着叛徒米奈希尔归来之时——他作为死亡骑士中的一员，把那柄被玷污的符文剑刺进了我的身体。$N，我求你，找到他，让他不安的灵魂得以安息。请代他的师父了结此事。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The broken blade you bring before me belonged to Razuv Ivaldi, one of Lordaerons strongest
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41354, '看来这颗紫水晶的附魔正在消退。请不必追问它为何如此运作——这个秘密，或许就该随我这座旧日家园一同消逝。$B$B唉，我欢迎你来到凯尔瑟利尔。这里曾是一座令人叹为观止的城市，如今则是我和我那些不安的同胞亡魂的居所。我不知道你为何来找我。我十分怀疑，你会为杀死因坎塔戈斯而愧疚。$B$B<阿尔多雷尔叹了口气。>$B$B一个愚蠢的儿子，想讨父亲欢心。可我又有什么资格、你又有什么资格去评判他的路？若你寻求答案，就只能通过帮助我来得到——一份人情，须以另一份人情来偿。徘徊在附近的那些上层精灵必须得到安息。整个湖面上都能看到他们无目的地飘荡。让他们解脱，你便会得到我的谢意。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- It appears the Amethyst is losing its enchantment. I would ask you not to question the way
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41355, '因坎塔戈斯盯上那座塔，是因为那里不稳定的地脉与残存的强烈能量。他想在蓝龙军团中扬名，推进他们在艾泽拉斯施行大沉寂的图谋。他求见玛里苟斯本人，但哈蕾拒绝了他这一特权，她认为他们还不到相见之时。$B$B我不清楚她的理由。老实说，眼见蓝龙对他们昔日的盟友也日渐咄咄逼人，我开始一天天质疑他们的所作所为。曾几何时，我还在我这座残破的家中款待过龙类。说来令人伤心，那样的日子已经过去，如今他们偷走了我一件神圣之物。$B$B在你进一步了解因坎塔戈斯的选择之前，先替我把一件东西取回来：一架借着附魔晶石得以望穿天穹的、纯净的月锻望远镜。$B$B他们应该把它带进了东南方的玛兹索瑞尔。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Incantagos sought the Tower for its unstable ley-lines, and the intense power that lingere
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41356, '因坎塔戈斯动身去东部王国之前，我曾想劝他几句——因为我确实曾是蓝龙的朋友。我告诉他，他盯上的那道地脉极不稳定，就连他这样的蓝龙也无法真正驾驭。唉，其实连我——甚至连那位伟大的守护者——都做不到。$B$B动身前，他选择在霜语峡谷歇息。不知为何，他在那些巨人之间找到了慰藉。巨龙陷入深眠时会蜕鳞。去找那些游荡巨人的晦气吧，虽说这或许会惹恼此地的元素。我们需要那些鳞片，它们能告诉我们更多。$B$B别退缩，朋友。也许你觉得我这些差事毫无意义，但我向你保证，此事不能置之不理。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Before Incantagos left for the Eastern Kingdoms I sought to give him counsel. For I truly 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41357, '看看吧，朋友。这些纯净的鳞片曾泛着碧蓝的光泽。可如今失了生机，反倒更像一块没打磨过的青金石。我并非对你有恶意，别担心。我只是为因坎塔戈斯的死而惋惜。要是我能再快一点，也许他就不会死。$B$B不管怎样，看来我们离真相仍未近一步。我就怕这样。因坎塔戈斯一死，这些鳞片上的魔力早已消散。我们可以暂时让它们重获生机，但要办到，就得从另一头蓝龙身上抽取生命注入其中，或者用类似的手段。$B$B恐怕你得再往东走一趟了，朋友。在如今人类最大的王国地下的牢狱里，你会找到它——那件可憎的造物。他为何要那样做，我永远想不明白。去找阿尔克提拉斯的活性碎片。在它的核心中，你能找到蓝龙真正的魔力——玛里苟斯的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Have a look friend. These pristine scales once shined embraced by an Azure tone. Yet now, 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41358, '有了这些物件，我终于能找到我们都在寻找的答案。给我片刻施法的时间。$B$B<阿尔多雷尔闭着眼低声哼唱。>$B$B这实在难以接受。我不知道该作何反应。我……我想这事也躲不掉了。阿里戈斯之所以盯上塔中的地脉，是因为蓝龙认为艾泽拉斯的凡人族裔不配拥有奥术。看来玛里苟斯本人正在准备一场……我不愿称之为战争，也不愿称之为战役。$B$B蚂蚁会把你的脚看作宣战或交战吗？还是纯粹的清除？我必须知道，是不是所有人都认为这条路是对的。我离不开此地，所以求你——求你代我去见哈蕾。她是卡利姆多的巢母。她栖于玛兹索瑞尔之巅，里面有一道符文，可供你抵达她那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- With these objects gathered I can finally find the answers we both seek. Allow me mere mom
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41359, '所以因坎塔戈斯死了。若不是阿尔多雷尔派你来的，我早就用牙齿而不是话语来招呼你了。唉，看来出乎意料之事又一次夺走了一名蓝龙的孩子。$B$B这一切都是真的，凡人。我们已准备好剥夺你们凡人族裔对奥术的使用权。希望你不敢质疑这一点。你们的愚蠢不仅带来了大分裂、该死的燃烧军团，以及随之而来的一切；还开了一道通往异界的门？好一桩壮举——代价是百万次的鲜血。$B$B作为这个世界的守护者，我们本该限制对奥术的接触。可你们全都变得如此自负，还相当强大。玛里苟斯大人——正是教导了第一批法师的那位——已认定你们不再配承担这份责任。艾泽拉斯能够自愈，新的种族也能诞生。$B$B有时，修补问题的最好方式就是一块空白的画布。把这当作警告吧，然后离开——对参与了因坎塔戈斯之终结的人，我还剩几分怜悯。告诉阿尔多雷尔，只有他一人会安然无恙。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- So Incantagos is dead. Were you not sent by AlDorel I would have used my teeth rather than
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41360, '看来因坎塔戈斯在他的追寻中并不孤单。他们怎能如此盲目、如此无情？他们必须明白，这不是他们该走的路。必须！$B$B<阿尔多雷尔叹了口气。>$B$B就是这样了，朋友。真相——即便你说出去，也没人会信。我们能做的只有——活下去。在这片寒冷的土地上，也要去感受太阳的暖意。关于终末与死亡的预言，永远不该阻止我们活在当下。别担心。尽管我曾是蓝龙的朋友，但我已做好准备，你也一样。$B$B终有一天，我们会再度相见。我祈祷那一天尽可能晚些到来。在那之前——来，我这有一件来自我们早已逝去之生活的信物，想赠予你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Incantagos was not alone in his quest it seems. How could they be so blind, so ruthless? T
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41361, '<刺鼻的烟气令人难以视物，但你在滚烫的地面上发现了一块鲜艳的水晶，烫得不能触碰。你判断它价值极高，却不敢贸然加工——你没有正确切割这块石头的本事。看来你得找个能教你这门手艺的人。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- <The unbearable fumes make it hard to see, but what you found on the simmering ground is a
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41362, '你的猜测没错，我确实能教你如何亲手切割山中之血。不过要办到，需要一套我弄不到的材料。这间仓库或许存货充裕，可索瑞森正谋划着那么多阴谋，好东西早就断供了。$B$B来，把这些材料带给我，我很乐意把黑铁矮人切割山中之血的古老手艺教给你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You are correct in your assumption; I indeed can teach you how to cut a Blood of the Mount
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41363, '你也许已经见过我的弟子阿兰德里安了。她主动去调查从哀嚎洞穴中爬出来的危险之物——那是灰谷以南贫瘠之地里一座被诅咒的洞穴迷宫。$B$B纳拉莱克斯的蠢行虽出于高尚——当然也天真——却给卡利姆多的平衡造成了无法弥补的损伤，最明显的便是那座石造迷宫中疯长的植物。其中一些已经开始自行移动，足以证明纳拉莱克斯无意间释放的力量有多大。我想研究这些植物，好与塞纳里奥议会一同拟定对策。$B$B把你在哀嚎洞穴里能找到的最凶暴的植物样本多带些来，你会得到应有的报酬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You mightve convened with my disciple Alanndrian already, she has taken it up herself to i
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41364, '你好，$N。还在找活干吗？有份报告需要送达到格伦郡的纳吉拉斯公爵那里。$B$B别担心，你不必亲手交到他手上。你只需把这卷卷轴交给亡灵卫兵马库斯，他应该就驻守在纳吉拉斯公爵常待的那座教堂外。$B$B内容无非是通知他们：我们已决定派冒险者进入影牙城堡。阿鲁高绝不能活着。去格伦郡并不难。你可以沿路向北走，也可以先回提瑞斯法林地，穿过索利登农庄抵达。随你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Hail $N. Still looking for more work? I have a report that needs to reach Duke Nargelas in
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41365, '格伦郡信奉圣光的人并不多，不过显然，那时我们都相信自己生于圣光之中。我们更在意的是守住自己的土地。即便到了如今——多亏那所谓的黑暗重生，我们得以再度行走——我的忠诚仍属于此地的百姓。我生前未能护住公爵，死后绝不会再失败。$B$B除了我的私心之外，也有必要说明我提出这一请求的理由。布莱特考坡弗神父曾在过去引领我们穿过刺目的圣光，如今又帮我们爬进阴影。他把被遗忘者的需要置于自己之前，无论生前死后，都同样无私。$B$B此地以北是洛丹伦残部最后一处营地。我们的辅祭，列兵威廉，就在其中游荡。我们下不了手杀他，所以请你代劳。据说威廉会在碎脊塔到营地入口之间巡逻。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Glenshire did not have many Light worshipers, although its clear that at the time we all b
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41366, '纳吉拉斯公爵与银松男爵生前是好友。正因他们彼此间的敬重与情谊，我也决定与银松要塞的主教保持密切往来。主教铁鬃很快成了我最亲近的朋友。他是个世上少有的人。$B$B有时我会专程离开格伦郡，只为去听他的布道。他讲述圣光与圣光带给他的安宁时，那种样子让我这个圣职人员自愧不如——甚至有些嫉妒。若他看到我现在这副模样，定会深感羞耻。$B$B<布莱特考坡弗神父停顿了几秒。>$B$B我知道这听起来很荒唐，$N，可我从那座已被腐化的要塞里听到了他灵魂的呼唤。鬼魂面对的是一种与我们不同的亡灵形态。巫妖王的掌控减弱后，我还能寻回自我，可他将永远困在时间中的某一处，甚至连自己已死都浑然不知。$B求你，让我的朋友安息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Duke Nargelas and the Baron of Silverlaine were good friends in life. Because of the respe
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41367, '唤醒纳拉莱克斯固然是你的首要目标，但还有别的事需要你去做。$B$B科卡尔人像蛇一样溜过裂隙，藏进了蜿蜒峡谷的一条支洞里。这场入侵中，我们试图杀掉每一个看到的敌人，可其中一个竟宣称哀嚎洞穴是他们的天赋之地。$B$B当然，差得远了。科卡尔人践踏大地母亲的慈爱，所到之处只留下毁灭！这个狂热的科卡尔人名叫赞达拉·风蹄。$B这话听着或许激进，但我要你把她的首级带来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- While waking Naralex should be your main goal, other things are required of you.$B$BThroug
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41368, '我们尽活人所能——呸！我他娘的受够了一副什么都没发生的样子！$B恭喜你，$N，你有幸听到我到底——有多——受够了。这一定很刺激吧？是不是？！$B$B<巴兹尔深深叹了口气。>$B$B抱歉，刚才脑子里忽然咯噔了一下。有点多愁善感了，你明白。$B我曾在如今被称为血色修道院的那地方当顶尖的铁匠。我还记得在圣光祝福下锻造护甲的那些日子。$B$B可如今，如今这些蛆虫，只要我提起我们昔日的信仰，他们就瞪着我。蠢货，全都是蠢货。$B也是运气，阿尔萨斯那邪种屠戮全城的那天我正好不在修道院里——而现在我却只能在这烂泥地里打铁。岂有此理，我告诉你，岂有此理！$B我的学徒达格尔姆应该还活在那边的军械库里。那蠢货大概拿着我关于光铸锭的日志——我要把它拿回来，哪怕你得从他冰冷的手指里掰出来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- We do what the living cann- bah! I am piss tired of acting like nothing happened!$BCongrat
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41369, '你身上散发着强大力量的痕迹，陌生人。那痕迹与那座被诅咒的高塔里、笼罩着这条死寂峡谷的力量如出一辙。仿佛已是万古之前，我们这些教堂的居民受命保管一件圣物——就是不久前汉瓦为你修复的那件。它是某件强大神器的一部分，一道不羁魔法的导管。它曾由守护者本人使用，如今已被损坏——那是一道保险，确保没有邪恶能像他当年那样滥用它来伤害艾泽拉斯。$B$B它的部件不仅散落在那座塔中，也散落在世界各地。若你在旅途中能集齐它们，就带来给我，我或许能让它们复原如初。不过要做到这一点，需要大量奥术能量。我离不开此地，所以就得由你把这样的东西带来。守护者的高塔应该是个合适的去处。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Vestiges of great power emanate from you, stranger. Vestiges akin to those circulating wit
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41370, '我从你身上感觉到的东西——这股麻痹般的热度，这么大的压迫，我几乎承受不住！你带回了权杖的头部，它渴望与另一半重逢。别再耽搁了，否则这些物件庞大的力量恐怕会无法承受。$B$B凭我之力，加上剩下的宇宙残渣，足以让麦迪文之杖重现昔日荣光。但那只是表面的复原。若不为它注入守护者的精华，这根权杖不过是一无是处的玩物——当年正是他的触碰唤醒了它。除非我们找到让它与麦迪文同调的办法，否则根本无法使用。$B$B既然守护者早已不在此地，寻找他留下的痕迹看来也毫无希望。求你——我们必须找到它，否则这根权杖将永远沉寂。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- What I sense from you - this paralyzing heat, so much pressure, I can barely take it! You 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41371, '权杖是完整的，可是……和我记忆中的不太一样。它外观毫无二致，散发的气息却迟钝、近乎空洞。守护者的力量固然清晰可辨，但权杖内部确实残留着一股陌生的能量。这股能量蛰伏着、沉睡着，渴望着被唤醒。$N，恐怕在把这股魔力从圣物中释放出来之前，我们还不算完。$B$B当我把心神集中于这件神器时，我看到了漂浮的岩石、饱受摧残的大地，以及自地面喷涌的火焰；一个游徙的秘法种族，被一道翠绿之焰所压制。$B$B$N，请原谅我帮不上更多忙。要驾驭权杖中那股陌生的魔力，我需要把一件来自我所描述的那个位面的、充满能量的物品与它调和。至于那样的东西该去哪里找，我却看不出来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The scepter is complete, yet... different to how I remembered it. It looks identical, but 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41372, '同调仪式会耗费我一些时间和精力。你准备好让我开始的时候，告诉我一声。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The attunement will take some of my time and energy. Please tell me once you wish me to st
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41373, '这本书的文字用的是极拖沓的地精俚语。翻过书页，你看到一些熟悉的菜谱，都不算特别有意思。你叹口气翻到下一页，发现少了一页。若不是这本书正好在这里结束，你本不会在意；可现在它偏偏就断在这儿，让你不禁琢磨起各种可能。$B$B合上书时，十几个「假如」掠过你的脑海。在封底你能辨认出一个名字：「伟大的加斯蒂诺」——这本平平无奇的书有什么了不起的？加斯蒂诺是谁，谁能告诉你更多？好奇心在你心底深处扎了根，你想起卡拉赞下层大厅里那位鬼魂厨师。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- The text is written in a very sluggish Goblin slang. As you circle through the pages famil
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41374, '你可能已经注意到，加斯蒂诺的菜谱书其实很常见。但里面确实有一道能让任何治疗者重振精神的配方。说来奇怪，尽管祭司们清楚那地精贪婪的野心，却又忍不住感激他留下的这道配方。$B$B某种程度上，我想他们是欣赏它的简单——毕竟那不过是一道什锦沙拉。可惜我记不住配方内容，不过我认为那缺失的一页应该就在墓穴里。这本书属于某个葬在那里的人。小心些，我觉得岁月对那地方并不仁慈。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Gastinos recipe book was quite common as you may have already noticed. But it did contain 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41375, '乍一看，这本书像是本再普通不过的典籍。可当你读起内容，很快就发现它更像一本潦草的日记，而非精心撰写的著作。按标题它自称是一份研究——可残破的书页与歪歪扭扭的字迹，像是出自孩童之手。$B$B“虽说我张开双臂欢迎古树与树人来到埃瑟瑞拉斯，我的许多同胞却觉得此举毫无必要。我们更熟悉奥术，在他们眼中，与这些魔法生物打交道是那些使用同类魔法的德鲁伊的事。然而仿佛是要气他们似的，随着时间推移，这两种魔法树木的形象似乎都适应得很好，有些树人甚至长出了蓝色的叶片。”$B$B你眯起眼睛，在你刚读过的文字下方辨认出一个名字：莱德罗斯。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Upon first glance, the book seemed to be a perfectly normal tome. Yet as you began to stud
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41376, '我认得这本日记。它曾是我为托塞德林王子保管的东西。我们常聚在一起讨论各种学问——不只是他和我，还有大多数博学者。埃瑟瑞拉斯曾是一座知识之城。可惜如今它只剩昔日的一道残影。多谢你把它带回来。$B$B若你有空，我有个请求。细看这部典籍时，我发现最后一页上刻着一个不完整的符文。既然我们的研究从未得出结论，我不得不请你前往扭木区，击败游荡在那里的受污染树人。若运气好，它们的枝叶上或许还残留着昔日点缀它们的蓝色。你要是能把那些叶片带给我，我就把我们研究的成果作为报酬给你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I do recognize this journal. It is something I used to keep for Prince Tortheldrin. We use
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41377, '现在，我需要些时间钻研乌尔的教诲。我必须确保不漏掉任何关键细节。这部典籍内容浩繁，而众所周知，乌尔会给那些心思敏锐的人留下暗藏的信息。$B$B在此期间，我有一件事交给你。世上的智者之中，少有人的智慧与洞见能及我们教团的领袖范达尔·鹿盔。他住在达纳苏斯。$B$B前往达纳苏斯，把你的发现告诉他。关于这件强大的神器，他一定会给出宝贵的见解。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Now, it will take me some time to delve into Urs teachings. I must ensure that no vital de
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41378, '伊露恩的奥秘深不可测，即便以我全部的学识，有时也觉得难以参透。我并不完全明白，她为何把月神镰刀这样的神器托付给瓦琳德——是的，那是她的名字。不过，它召唤狼人的力量，或许正是揭开其更深层真相的钥匙。$B$B我长期研究一种奇特的草药，名为明日草。有趣的是，我的研究表明，它或许对清除镰刀滞留卡拉赞期间沾染的黑暗能量极为关键。但要激活明日草，需要一种强效的催化剂。因此，给我带血来——狼人之血，取自潜伏在卡拉赞最幽深角落、游荡在吉尔尼斯城废弃街道、藏身于影牙城堡阴影中的各个部族。$B$B照办，把它们带来给我。不要耽搁。镰刀的力量必须由像我这样有能力的人来驾驭与理解。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Elunes mysteries are profound, and even I, with all my knowledge, can find them inscrutabl
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41379, '我一如既往，是对的。多亏了明日草，你收集的狼人之血中的黑暗已被我成功清除。现在，看！$B$B<大德鲁伊范达尔·鹿盔伸出手，展示一小瓶纯净的蓝色血液。>$B$B这在你看来也许不算什么，但你眼前的，不只是他们血统强韧的证明，也是他们与伊露恩之间联系的证明。再仔细看看。你在他们的血里看出来了吗？$B$B没错。与我们月井之水一般纯净。在血魔法玷污这个种族之前，他们本就是这样。立刻把它带给梦风。他知道接下来该怎么做。$B$B还有，若你哪天觉得肩上的镰刀过于沉重、难以承担……你知道在哪里能找到我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I was right, as always. Thanks to the morrowgrain, I have successfully purged the darkness
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41380, '现在，我需要些时间钻研乌尔的教诲。我必须确保不漏掉任何关键细节。这部典籍内容浩繁，而众所周知，乌尔会给那些心思敏锐的人留下暗藏的信息。$B$B在此期间，我有一件事交给你。世上的智者之中，少有人的智慧与洞见能及我们教团的领袖范达尔·鹿盔。不过，我担心他不像我这样乐于接纳你。$B$B但也不是毫无希望。在你的牛头人盟友中，有一位几乎与范达尔同样睿智。我说的是玛加萨·野性图腾。尽管她的部族时而桀骜难驯，他们却始终敬奉伊露恩——他们称她为穆沙。$B$B据我所知，她如今住在伟大的雷霆崖。去那里寻求她的建议吧。也许她掌握的关于镰刀的学识，连我都未曾触及。你的旅程远未结束，而野性图腾的智慧或许弥足珍贵。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Now, it will take me some time to delve into Urs teachings. I must ensure that no vital de
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41381, '关于这件武器以及它所遭遇的邪恶命运，我听过许多传说。但还未到绝望之时——我们也许能把它从卡拉赞的黑暗中净化出来。$B$B近来，塞纳里奥议会的一些成员，尤其是与范达尔·鹿盔最亲近的那些人，开始囤积大量一种名为明日草的草药。据大德鲁伊哈缪尔告诉我的情况，我相信这种草药或许正是净化镰刀的关键。$B$B不过要让它起效，还需要一种强效的催化剂。我们需要狼人之血——取自潜伏在卡拉赞最幽深角落、游荡在吉尔尼斯城被遗弃的街道、藏身于影牙城堡阴影中的各个部族。$B$B集齐他们的血交给我。我们或许还来得及净化镰刀，让它回归真正的用途。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- I have heard many tales of this weapon and the vile fate that befell it. Yet, not all is l
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41382, '范达尔那帮手下拿明日草筹划的东西，必定非同小可……不过我扯远了。血确实已经净化。来看看吧，孩子。$B$B<玛加萨·野性图腾伸出手，展示一小瓶纯净的蓝色血液。>$B$B如月井之水般纯净，像星辰本身那样闪耀。在这些狼人遭遇那可怕的命运之前，他们无疑是穆沙最宠爱的孩子。$B$B立刻把它带回给梦风。他会想知道这件事。$B$B还有，把镰刀带在身边。塞纳里奥议会里有些人，未必乐意看到它在你手上。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Whatever Fandrals lackeys are planning with morrowgrain must be truly extraordinary... But
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41383, '你不在的时候，我深入钻研了乌尔的教诲，逐页、逐字地审视了典籍中每一个字句与每一层隐意。我揭开的真相既令人豁然开朗，又令人深感不安。$B$B留下来听一会儿吧，年轻的 $r。乌尔文字中蕴含的智慧深不可测，但它也揭示了一个关于月神镰刀及其力量本质的残酷真相。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- During your absence, I delved deep into the teachings of Ur, scrutinizing every passage, e
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41384, '是时候干掉守护者怒月了。我们世界的命运系于此举。他在卡拉赞的存在是一块无法容忍的毒瘤，他的谋划必须在得逞之前被挫败。自然本身的平衡已岌岌可危。$B$B你为寻找那部典籍已经进过卡拉赞的上层大厅，对那里迷宫般的回廊与幽暗的殿堂并不陌生。前路不会轻松，但你先前的经历会派上用场。怒月已盘踞在卡拉赞黑暗魔法的心脏地带，从这片被诅咒的地方汲取力量，供养他邪恶的计划。$B$B但要当心，怒月绝非寻常对手。他是一位拥有传说级力量的血法师，数百年来钻研最黑暗的技艺，对血魔法的掌控无人能及。独自面对他无异于自寻死路。你需要盟友——强大而勇敢的同伴，与你一同迎向黑暗的洪流。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- It is time to bring down Keeper Gnarlmoon. The fate of our world depends on it. His presen
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41385, '我的渡鸦低语着一个曾笼罩吉尔尼斯城街巷的黑暗存在。在远隔重洋的阴霾与迷雾之中，有人见过一位狼人血法师编织他那邪恶的魔法。这生物已在那个本就多难的国度留下无法抹去的痕迹。细节所传甚少，但有一点可以肯定：他常与吉尔尼斯那对臭名昭著的摄政者夫妇——哈洛家——暗中勾结。$B$B哈洛家是个狡诈而冷酷的家族。据说只要能推进他们的野心，他们愿意与任何人结盟，不惜代价。那血法师在他们身上找到了甘愿配合的同谋——只要符合自身需要，他们便对他的黑暗行径视而不见。而解开血法师计划的关键，也许就藏在他们那些见不得光的交易里。$B$B若我能离开海加尔的圣林，我会亲自前往吉尔尼斯。可你，年轻人，拥有我求之不得的自由，能去到我去不了的地方。你的路很清楚，它通向那座迷雾笼罩的吉尔尼斯城。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- My ravens have whispered of a dark presence that once shadowed the streets of Gilneas City
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41386, '在乌尔写下的古老典籍中，有低语说：只要念出那普里科利希的名字，便如同竖起信标，把他的黑暗存在引入我们的世界。但你要仔细听好——有一种计策，一个巧妙的手段，能诱他前来、落入我们的掌控。$B$B拿上这颗奥术宝珠，它是远古的遗物，灌注着原始魔法的精华。带着它向西，前往一处古老能量法阵的所在——那是原始而强大的能量的交汇之地。在那里，在低语的风与沙沙作响的树叶之间，念出那普里科利希的名字。$B$B但务必谨慎，必须精确地安排他的到来。一旦他被召唤出来，我们便借法阵之力将他困住，剥去他的黑暗力量，让他变得脆弱。就在那一刻的虚弱中，我们将出手，把他驱逐回他来的阴影里，从此永远保障我们的世界不受他邪恶之手的侵扰。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- In the annals of ancient lore penned by Ur, it is whispered that the mere utterance of the
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41387, '你走到我面前来了。想必是来求教战艺——不然你找军械大师做什么。想精通武艺的人多得数不清，可真正做到的能有几个？我早已记不清有多少轻信而天真的战士自以为配得上我的教导，结果一遇到小小的考验就败下阵来。除非你能向我证明你的价值，否则我无法确信你担得起接下来的事。$B$B北面高山之上有一片被玷污的森林，名为费伍德。再往北，你会找到铁树洞穴；我要你去那里的洞穴中取一根根须——冷如钢铁，重也如钢铁。把它拔出来，平安带回来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- So you step before me. Surely to seek tutelage in the art of war - why else would you sear
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41388, '请原谅我粗鲁的态度，但我必须确认你是否适合走战争这条路。你或许在武艺上有些经验，但要追随我的道路，你目前做到的还远远不够。$B$B如先前所说，许多雄心勃勃的人都曾站在你现在的位置，可只有少数人成功了。从错误中学习——自己的错误，别人的错误——至关重要。去和我从前的弟子谈谈，他们会讲述失败的故事。只有当你真正理解他们的过失，你才能继续前行。在这座岛上找萨克戈斯和克兰诺克，在塔纳利斯找卡法伊——我听说沙漠的刺激把他引到了加基森。办完之后回来，就他们讲述的内容回答我的问题。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Apologies for my brash demeanour, but I have to make sure you are cut out for the path of 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41389, '来，拿上这颗玻璃弹珠，带去给萨克戈斯。它证明了你的事迹，也标志着你与他平起平坐。时刻保持警觉，记住你学到的东西。我很期待看到你进一步的成长！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Here, take the glass marble and bring it to Sakgoth. It is proof of your deeds and signals
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41390, '喂，你。是正好要去西部荒野吗？军情七处拿到了一条重要线索：迪菲亚的阴谋牵涉到西部荒野之外的人。我们怀疑他们在经手某种极易挥发的化学品，它不仅威胁暴风城，也威胁东部王国其他地方。我们大概需要一些……额外的帮手，因为这次的任务多半不适合潜行。$B$B我们有一名特工驻扎在西部荒野，就在通往暮色森林的那座桥边、废弃法师塔附近。我要你去见她，而且要快。那边事态突然有了值得调查的变化。她叫吉尔妮；找到她之后，照她说的做。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Hey, you. Headed to Westfall, by chance? The SI:7 is on a big lead about the Defias machin
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41391, '我已经监视这座塔很久了，围绕它发生的一切都怪异得难以理解。这里的迪菲亚人不多，但装备精良。单这一点就够让人担心了，可最让我困惑的是那些在周边巡逻的僵尸。时不时有些迪菲亚人走进塔里；可他们没再出来，取而代之的是一种全新的僵尸露着丑脸走出来。$B$B我想进一步调查塔内部的门道，但我在等军情七处的增援。你来的目的很简单，却也更关键。塔边的码头上，我看到一个鬼鬼祟祟的地精女在系她的划艇，船上载满了箱子。肯定是某种送货，但我们要的是文件——最好是载有参与这些勾当者姓名的文件。你要怎么处理她随你，但要把任何有价值的情报送回军情七处总部的伦兹克那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Ive been spying on this tower for quite some time and anything happening around it is unfa
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41392, '贾里德·沃斯是威廉·沃斯之子，后者是位技艺高超、学识渊博的炼金师。他的父亲在旧城区开着一间炼金店，很受爱戴。暴风城第二次被焚毁时，他家也在烧成灰烬之列。石匠工会重建城市期间，沃斯自然以为凭他作为暴风城最著名炼金师的身份，宅子会被归还——讽刺的是，事情并未如此。$B$B暴风城的贵族们对重建另有打算，最终沃斯一家沦落街头。怀着日益增长的心头恨意，他诅咒那些该为他们命运负责的人。我们推测，沃斯在死前把儿子送去了石匠工会，而儿子也承袭了他的怨恨。看来贾里德在仇恨与本领两方面都继承了父亲。$B$B$N，不能再让沃斯继续活动了。据你带来的名单，他藏身于死亡矿井。除掉他，把他最新调配的药剂样本带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Jared Voss is the son of William Voss, a highly skilled and educated alchemist. His father
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41393, '你有钢铁般的意志，也能从过往的错误中汲取智慧。现在，向我展示你拥有的力量。我长话短说，听好了。$B$B在遥远东方，赤脊山以北的燃烧平原上，沉睡着一头闷燃的巨人，他的力量无与伦比。去北面的群山中搜寻，杀死那头火热的巨兽，把他燃烧的眼睛带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You possess an iron will. You draw wisdom out of past mistakes. Now demonstrate to me the 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41394, '随着普里科利希们的影子渐渐淡去、影响日渐消退，净化月神镰刀的时候到了。然而这绝非易事——编织在它本质之中的黑暗魔法根须，早已深深扎入。$B$B靠近些，年轻人，听我说。要开始净化，我们需要六块永恒梦境石与二十卷月布。这些碎片将成为我们大业的基石，作为净化能量的导管，让它们从中流过。$B$B但通往纯净之路危机四伏，因为盘踞在镰刀中的黑暗魔法渴望再次向世界释放。要容纳如此强大的力量，我们必须打造一件无与伦比的容器——一头强大恶魔的灵魂。在虚空的队列中，有低语提到一位名叫梅菲斯托洛斯的恐惧魔王。$B$B深入虚空，寻找梅菲斯托洛斯灵魂的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- With the lingering shadows of the pricoliches dead and their influence waning, the time ha
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41396, '$N，请稍等一下。刚才，我从祖父的灵魂碎片中感到一股能量涌动。一份久违了数千年的、令人安心的温暖。可这只是其一。说来难解，但我感到伟大的玛洛恩正试图与我们——与你——沟通。我能感到他存在中的急切。只可能是这件事：玛洛恩想赐福于你，我确信无疑。$B$B要接受祖父的赐福，你必须与翡翠梦境同调，一如我那样。然而，要与伊瑟拉的领域同调，是资深德鲁伊经年累月冥想之后才能做到的事。不过，还有另一条路。那需要准备。帮我一把，$N，我就为你铺就获得梦境视界的道路。$B$B首先，我们需要一块梦幕，用梦皮与梦线织成。此外，还需要浸透梦境能量的碧绿蘑菇——去菲拉斯的翡翠湖找。最后，给我带充足的无梦安眠药剂来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- $N, please halt for a moment. Just now, I felt a surge of energy from my grandfathers spir
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41397, '凭借梦境视界这份绿龙的古老天赋，你或许能看穿梦境的帷幕，直接与祖父交谈。绿龙军团中曾有一位善良的楷模，维瑟库斯，他格外喜爱凡人族裔。他被称为「永恒的沉眠者」，进入了无尽的冥想，最终舍下了肉身，把灵魂锚定于梦境。你要找的就是他。找到他的遗骸，点燃我用剩余蘑菇制成的这束香，它应当能让你召出他的灵魂。$B$B我最后一次见到维瑟库斯远在大分裂之前，所以我不知他的遗骸如今何在。可林木间低语着一个名字——瑟拉丹。去那里寻找，我确信你会找到维瑟库斯。别忘了戴上梦幕！它的保护或许不强，但足以撑过你与维瑟库斯的交谈。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- With the gift of Dreamsight, an ancient ability of the green dragons, you may be able to s
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41399, '上一场战争中，无数英雄倒下了；直到今天，仍有无数人死于天灾之手。天灾会从阵亡者的尸体上剥下护甲，带回纳克萨玛斯，用途不明。$B$B在这些物件之中，偶尔能发现一枚被亵渎的印章戒指。你必须把它交还给我，我会将它净化成你能用得上的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Many heroes fell in the last war and many continue to perish at the hands of the Scourge t
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41400, '你取得了怒风的衣装，$C。我能感到你身上自然本身的气息，可它显得黯淡。也许你身上带着的这套，并不适合你愿意承担的任务。$B$B<卡祖德低吟了几秒。>$B$B把它交过来，然后告诉我：你忠于自己的天性吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- You have claimed the garments of Stormrage, $C. I can sense Nature itself in you, yet it s
